INSERT INTO hackathon_announcement (id, pinned, status, published_at, created_by, created_at, updated_at) VALUES ('p-jadwal', 1, 'published', 1792551600000, 'seed', 1792551600000, 1792551600000);
INSERT INTO hackathon_announcement_i18n VALUES ('p-jadwal', 'id', 'Jadwal finalis dan Demo Day', 'Finalis diumumkan 14 Nov, Demo Day & Awarding 27 Nov di Jakarta.', 'Setelah batas pengumpulan karya 1 Nov 23.59 WIB, panitia menilai semua project yang masuk.

Finalis diumumkan pada 14 Nov. Finalis mempresentasikan karyanya di Demo Day & Awarding, 27 Nov pukul 13.00–16.00 WIB di Jakarta.

Juara 1, 2, dan 3 diumumkan di acara tersebut.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-jadwal', 'en', 'Finalist and Demo Day schedule', 'Finalists announced Nov 14, Demo Day & Awarding Nov 27 in Jakarta.', 'After the submission deadline on Nov 1, 23:59 WIB, the organizers review every submitted project.

Finalists are announced on Nov 14. They present their work at Demo Day & Awarding on Nov 27, 13:00–16:00 WIB in Jakarta.

1st, 2nd, and 3rd place are announced at the event.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-jadwal', 'zh', '决赛名单与 Demo Day 日程', '11 月 14 日公布决赛名单，11 月 27 日在雅加达举行 Demo Day 及颁奖。', '11 月 1 日 23:59（WIB）作品提交截止后，主办方将评审所有提交的项目。

决赛名单于 11 月 14 日公布。入围团队将在 11 月 27 日 13:00–16:00（WIB）于雅加达举行的 Demo Day 及颁奖典礼上展示作品。

第一、二、三名将在活动现场公布。');
INSERT INTO hackathon_announcement (id, pinned, status, published_at, created_by, created_at, updated_at) VALUES ('p-batas-1-nov', 0, 'published', 1792548000000, 'seed', 1792548000000, 1792548000000);
INSERT INTO hackathon_announcement_i18n VALUES ('p-batas-1-nov', 'id', 'Pengingat: batas pendaftaran 1 Nov 23.59 WIB', 'Pendaftaran tim dan pengumpulan karya ditutup 1 Nov pukul 23.59 WIB.', 'Pasar tim dan pendaftaran ditutup pada 1 Nov pukul 23.59 WIB. Karya Agentic AI dikumpulkan sebelum batas yang sama.

Pastikan tim sudah terdaftar di portal Tencent (langkah 2) dan project sudah dikirim (langkah 3) sebelum batas waktu.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-batas-1-nov', 'en', 'Reminder: registration closes Nov 1, 23:59 WIB', 'Team registration and submissions close Nov 1 at 23:59 WIB.', 'The team market and registration close on Nov 1 at 23:59 WIB. Agentic AI projects are due by the same deadline.

Make sure your team is registered on the Tencent portal (step 2) and your project is submitted (step 3) before the deadline.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-batas-1-nov', 'zh', '提醒：报名于 11 月 1 日 23:59（WIB）截止', '团队报名与作品提交于 11 月 1 日 23:59（WIB）截止。', '团队市场与报名于 11 月 1 日 23:59（WIB）关闭。Agentic AI 作品须在同一截止时间前提交。

请确保在截止前已在腾讯门户注册团队（第 2 步）并提交项目（第 3 步）。');
INSERT INTO hackathon_announcement (id, pinned, status, published_at, created_by, created_at, updated_at) VALUES ('p-aturan-tim', 0, 'published', 1792389600000, 'seed', 1792389600000, 1792389600000);
INSERT INTO hackathon_announcement_i18n VALUES ('p-aturan-tim', 'id', 'Aturan bentuk tim: keputusan owner maksimal 24 jam', 'Lamaran yang tidak diputuskan owner dalam 24 jam ditolak otomatis.', 'Satu orang hanya bisa menjadi anggota satu tim atau owner satu tim, dan hanya boleh punya satu lamaran aktif.

Owner punya waktu 24 jam sejak lamaran masuk untuk menyetujui atau menolak. Lewat dari itu, lamaran otomatis ditolak supaya pelamar bisa mencari tim lain.

Selama menunggu, pelamar boleh menarik lamarannya. Setelah disetujui, anggota bisa melihat anggota tim lain beserta kontaknya dan chat di ruang tim.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-aturan-tim', 'en', 'Team rule: owners decide within 24 hours', 'Applications not decided by the owner within 24 hours are rejected automatically.', 'One person can be a member of one team or the owner of one team, and may have only one active application.

Owners have 24 hours from when an application arrives to approve or reject it. After that it is rejected automatically so the applicant can look for another team.

While waiting, applicants may withdraw. Once approved, members can see the other team members with their contacts and chat in the team room.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-aturan-tim', 'zh', '组队规则：队长须在 24 小时内决定', '队长 24 小时内未处理的申请将被自动拒绝。', '每人只能成为一个团队的成员或一个团队的队长，且同一时间只能有一个有效申请。

队长自收到申请起有 24 小时决定批准或拒绝。超时后申请将被自动拒绝，以便申请人寻找其他团队。

等待期间申请人可以撤回申请。获批后，成员可查看其他成员及其联系方式，并在团队空间中聊天。');
INSERT INTO hackathon_announcement (id, pinned, status, published_at, created_by, created_at, updated_at) VALUES ('p-dibuka', 0, 'published', 1792029600000, 'seed', 1792029600000, 1792029600000);
INSERT INTO hackathon_announcement_i18n VALUES ('p-dibuka', 'id', 'Pendaftaran AI Agent Hackathon dibuka', 'Daftar di portal ini, daftarkan tim ke Tencent, lalu submit project.', 'Pendaftaran dibuka 15 Okt. Alurnya tiga langkah: daftar di portal ini (data, skenario, grup utama, tim), daftarkan tim ke portal Tencent, lalu submit project.

Gabung grup WhatsApp utama untuk menerima info resmi dari panitia.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-dibuka', 'en', 'AI Agent Hackathon registration is open', 'Register on this portal, register your team with Tencent, then submit your project.', 'Registration opened on Oct 15. There are three steps: register on this portal (details, scenarios, main group, team), register your team on the Tencent portal, then submit your project.

Join the main WhatsApp group to receive official updates from the organizers.');
INSERT INTO hackathon_announcement_i18n VALUES ('p-dibuka', 'zh', 'AI Agent Hackathon 报名开启', '在本门户报名，向腾讯注册团队，然后提交项目。', '报名于 10 月 15 日开启。共三步：在本门户报名（资料、情景、主群、团队），在腾讯门户注册团队，然后提交项目。

加入 WhatsApp 主群以接收主办方的官方通知。');
